import type { TemplateSet } from './templates';

export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  html: string;
  markdown: string;
  data: Record<string, unknown>;
  template?: string;
  layout?: string;
}

export interface SSGConfig {
  plugins?: string[];
}

export interface PluginContext {
  config: SSGConfig;
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  pages: Page[];
  templates: TemplateSet;
  output: Record<string, unknown>;
}

export type PluginHook = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onFile' | 'onEnd';

export const PLUGIN_HOOKS: readonly PluginHook[] = [
  'onStart',
  'beforeBuild',
  'afterBuild',
  'onFile',
  'onEnd',
];

export interface Plugin {
  name: string;
  onStart?(ctx: PluginContext): void | Promise<void>;
  beforeBuild?(ctx: PluginContext): void | Promise<void>;
  afterBuild?(ctx: PluginContext): void | Promise<void>;
  onFile?(page: Page, ctx: PluginContext): void | Promise<void>;
  onEnd?(ctx: PluginContext): void | Promise<void>;
}

import type { Page, Plugin, PluginContext, PluginHook } from './types';

export type { Page, Plugin, PluginContext, PluginHook, SSGConfig } from './types';
export { PLUGIN_HOOKS } from './types';

export class PluginPipeline {
  private readonly plugins: Plugin[] = [];

  add(plugin: Plugin): void {
    this.plugins.push(plugin);
  }

  get size(): number {
    return this.plugins.length;
  }

  list(): Plugin[] {
    return [...this.plugins];
  }

  run(hook: PluginHook, ...args: unknown[]): void {
    for (const plugin of this.plugins) {
      const fn = plugin[hook];
      if (typeof fn === 'function') {
        (fn as (...a: unknown[]) => void).apply(plugin, args);
      }
    }
  }

  async runAsync(hook: PluginHook, ...args: unknown[]): Promise<void> {
    for (const plugin of this.plugins) {
      const fn = plugin[hook];
      if (typeof fn === 'function') {
        await (fn as (...a: unknown[]) => void | Promise<void>).apply(plugin, args);
      }
    }
  }

  onStart(ctx: PluginContext): void {
    this.run('onStart', ctx);
  }

  beforeBuild(ctx: PluginContext): void {
    this.run('beforeBuild', ctx);
  }

  afterBuild(ctx: PluginContext): void {
    this.run('afterBuild', ctx);
  }

  onFile(page: Page, ctx: PluginContext): void {
    this.run('onFile', page, ctx);
  }

  onEnd(ctx: PluginContext): void {
    this.run('onEnd', ctx);
  }
}

import fs from 'fs';
import path from 'path';
import ts from 'typescript';
import type { Plugin, SSGConfig } from './types';
import { PLUGIN_HOOKS } from './types';

export const DEFAULT_CONFIG_FILE = 'ssg.config.ts';
export const DEFAULT_PLUGINS_DIR = './plugins';

export function ensureTypeScriptLoader(): void {
  if (require.extensions['.ts'] !== undefined) return;
  require.extensions['.ts'] = (module: NodeModule, filename: string) => {
    const source = fs.readFileSync(filename, 'utf8');
    const { outputText } = ts.transpileModule(source, {
      fileName: filename,
      compilerOptions: {
        module: ts.ModuleKind.CommonJS,
        target: ts.ScriptTarget.ES2020,
        esModuleInterop: true,
        moduleResolution: ts.ModuleResolutionKind.NodeJs,
      },
    });
    module._compile(outputText, filename);
  };
}

export function loadTsModule(filename: string): unknown {
  ensureTypeScriptLoader();
  return require(filename);
}

export function resolveConfigPath(configPath?: string): string | null {
  const candidate = configPath ? path.resolve(configPath) : path.resolve(DEFAULT_CONFIG_FILE);
  return fs.existsSync(candidate) && fs.statSync(candidate).isFile() ? candidate : null;
}

export function normalizeConfig(value: unknown): SSGConfig {
  const mod = (value as { default?: unknown } | null)?.default ?? value;
  if (mod && typeof mod === 'object' && !Array.isArray(mod)) {
    const plugins = (mod as Partial<SSGConfig>).plugins;
    return { plugins: Array.isArray(plugins) ? plugins.map(String) : [] };
  }
  return { plugins: [] };
}

export function loadConfig(configPath?: string): SSGConfig {
  const resolved = resolveConfigPath(configPath);
  if (!resolved) return { plugins: [] };
  return normalizeConfig(loadTsModule(resolved));
}

export function toPlugin(value: unknown, name?: string): Plugin | null {
  const mod = (value as { default?: unknown } | null)?.default ?? value;
  let candidate = mod;
  if (typeof candidate === 'function') {
    const proto = (candidate as { prototype?: object }).prototype;
    const isClass =
      !!proto && PLUGIN_HOOKS.some((hook) => typeof (proto as Record<string, unknown>)[hook] === 'function');
    try {
      candidate = isClass ? new (candidate as new () => unknown)() : (candidate as () => unknown)();
    } catch {
      return null;
    }
  }
  if (!candidate || typeof candidate !== 'object') return null;
  const plugin = candidate as Plugin;
  if (typeof plugin.name !== 'string' || plugin.name.trim() === '') {
    plugin.name = name?.trim() || 'anonymous';
  }
  return plugin;
}

export function loadPlugin(spec: string, baseDir: string = process.cwd()): Plugin | null {
  ensureTypeScriptLoader();
  try {
    if (spec.startsWith('./') || spec.startsWith('../') || path.isAbsolute(spec)) {
      let target = path.resolve(baseDir, spec);
      if (!fs.existsSync(target)) {
        if (fs.existsSync(target + '.ts')) target += '.ts';
        else if (fs.existsSync(target + '.js')) target += '.js';
        else if (fs.existsSync(path.join(target, 'index.ts'))) target = path.join(target, 'index.ts');
        else if (fs.existsSync(path.join(target, 'index.js'))) target = path.join(target, 'index.js');
      }
      if (!fs.existsSync(target)) return null;
      return toPlugin(require(target), spec);
    }
    return toPlugin(require(spec), spec);
  } catch {
    return null;
  }
}

export function loadPluginsFromConfig(config: SSGConfig, baseDir: string = process.cwd()): Plugin[] {
  const plugins: Plugin[] = [];
  for (const entry of config.plugins ?? []) {
    const plugin = loadPlugin(entry, baseDir);
    if (plugin) plugins.push(plugin);
  }
  return plugins;
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import type { Page } from './types';

marked.setOptions({ gfm: true, headerIds: false });

export const DEFAULT_CONTENT_DIR = './content';

export const FRONTMATTER_DELIMITERS: [string, string] = ['<!--', '-->'];

export function parseMarkdown(raw: string, slug: string): Page {
  const { data, content } = matter(raw, { delimiters: FRONTMATTER_DELIMITERS });

  const title = typeof data.title === 'string' && data.title.trim() !== ''
    ? data.title
    : slug;

  let date: string | undefined;
  if (data.date !== undefined && data.date !== null && String(data.date).trim() !== '') {
    date = data.date instanceof Date
      ? data.date.toISOString().slice(0, 10)
      : String(data.date);
  }

  const tags = Array.isArray(data.tags)
    ? data.tags.map((tag: unknown) => String(tag))
    : [];

  const template =
    typeof data.template === 'string' && data.template.trim() !== ''
      ? data.template.trim()
      : undefined;
  const layout =
    typeof data.layout === 'string' && data.layout.trim() !== ''
      ? data.layout.trim()
      : undefined;

  const html = marked.parse(content) as string;

  return { slug, title, date, tags, html, markdown: content, data, template, layout };
}

export function readPages(contentDir: string): Page[] {
  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }

  const entries = fs.readdirSync(contentDir, { withFileTypes: true });
  const files = entries
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.md'))
    .sort((a, b) => a.name.localeCompare(b.name));

  return files.map((entry) => {
    const slug = path.basename(entry.name, path.extname(entry.name));
    const raw = fs.readFileSync(path.join(contentDir, entry.name), 'utf8');
    return parseMarkdown(raw, slug);
  });
}

export function sortPages(pages: Page[]): Page[] {
  return [...pages].sort((a, b) => {
    if (a.date && b.date) return b.date.localeCompare(a.date);
    if (a.date) return -1;
    if (b.date) return 1;
    return 0;
  });
}

import type { Page } from './types';
import {
  DEFAULT_LAYOUT,
  DEFAULT_TEMPLATE,
  renderTemplateFile,
  TemplateSet,
} from './templates';

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function pageContext(page: Page): Record<string, unknown> {
  return {
    ...page.data,
    slug: page.slug,
    title: page.title,
    date: page.date,
    tags: page.tags,
    html: page.html,
    markdown: page.markdown,
  };
}

export function renderPageWithTemplates(page: Page, templates: TemplateSet): string {
  const templateName = page.template ?? DEFAULT_TEMPLATE;
  if (page.template !== undefined && !templates.templates.has(templateName)) {
    throw new Error(`Template not found: ${templateName}`);
  }

  const template = templates.templates.get(templateName);
  if (!template) return renderPage(page);

  const partials = [...templates.partials.values()];
  const content = renderTemplateFile(template, pageContext(page), partials);

  const layoutName = page.layout ?? DEFAULT_LAYOUT;
  if (page.layout !== undefined && !templates.layouts.has(layoutName)) {
    throw new Error(`Layout not found: ${layoutName}`);
  }

  const layout = templates.layouts.get(layoutName);
  if (!layout) return content;

  const context = { ...pageContext(page), body: content };
  return renderTemplateFile(layout, context, partials);
}

export function renderIndexWithTemplates(pages: Page[], templates: TemplateSet): string {
  const template = templates.templates.get('index');
  if (!template) return renderIndex(pages);

  const partials = [...templates.partials.values()];
  const context: Record<string, unknown> = { pages: pages.map(pageContext) };
  const content = renderTemplateFile(template, context, partials);

  const layout = templates.layouts.get(DEFAULT_LAYOUT);
  if (!layout) return content;

  return renderTemplateFile(layout, { ...context, body: content }, partials);
}

export function renderPage(page: Page): string {
  const title = escapeHtml(page.title);
  const tagLine = page.tags.length > 0
    ? `<p class="tags">Tags: ${page.tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ')}</p>`
    : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title}</title>
</head>
<body>
<article>
<h1>${title}</h1>
${page.date ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : ''}
${tagLine}
${page.html}
</article>
</body>
</html>
`;
}

export function renderIndex(pages: Page[]): string {
  const listItems = pages
    .map((page) => {
      const date = page.date ? ` &mdash; <time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
      return `  <li><a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.title)}</a>${date}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Home</title>
</head>
<body>
<main>
<h1>Pages</h1>
<ul>
${listItems}
</ul>
</main>
</body>
</html>
`;
}

import type { Plugin, PluginContext } from '../types';
import { readPages, sortPages } from '../markdown';

export class MarkdownPlugin implements Plugin {
  readonly name = 'markdown';

  beforeBuild(ctx: PluginContext): void {
    ctx.pages = sortPages(readPages(ctx.contentDir));
  }
}

import fs from 'fs';
import path from 'path';
import type { Page, Plugin, PluginContext } from '../types';
import { loadTemplates } from '../templates';
import { renderIndexWithTemplates, renderPageWithTemplates } from '../render';

export class TemplatePlugin implements Plugin {
  readonly name = 'template';

  beforeBuild(ctx: PluginContext): void {
    ctx.templates = loadTemplates(ctx.templatesDir);
  }

  onFile(page: Page, ctx: PluginContext): void {
    const html = renderPageWithTemplates(page, ctx.templates);
    fs.writeFileSync(path.join(ctx.outputDir, `${page.slug}.html`), html, 'utf8');
  }

  afterBuild(ctx: PluginContext): void {
    const html = renderIndexWithTemplates(ctx.pages, ctx.templates);
    fs.writeFileSync(path.join(ctx.outputDir, 'index.html'), html, 'utf8');
  }
}

import type { Page, Plugin, PluginContext } from '../types';

export const LIVE_RELOAD_SCRIPT_ID = 'ssg-live-reload';

export const WS_PATH = '/live-reload';

export function liveReloadScript(port: number): string {
  return `<script id="${LIVE_RELOAD_SCRIPT_ID}">
(function () {
  var port = ${port};
  function connect() {
    var proto = location.protocol === 'https:' ? 'wss:' : 'ws:';
    var ws = new WebSocket(proto + '//' + location.hostname + ':' + port + '${WS_PATH}');
    ws.onmessage = function () { location.reload(); };
    ws.onclose = function () { setTimeout(connect, 1000); };
    ws.onerror = function () { ws.close(); };
  }
  connect();
})();
</script>`;
}

export function injectLiveReload(html: string, port: number): string {
  const script = liveReloadScript(port);
  if (/<\/body>/i.test(html)) {
    return html.replace(/<\/body>/i, `${script}\n</body>`);
  }
  return `${html}\n${script}`;
}

export class DevServerPlugin implements Plugin {
  readonly name = 'dev-server';

  liveReloadScript(port: number): string {
    return liveReloadScript(port);
  }

  injectLiveReload(html: string, port: number): string {
    return injectLiveReload(html, port);
  }

  onStart(_ctx: PluginContext): void {}

  beforeBuild(_ctx: PluginContext): void {}

  afterBuild(_ctx: PluginContext): void {}

  onFile(_page: Page, _ctx: PluginContext): void {}

  onEnd(_ctx: PluginContext): void {}
}

import fs from 'fs';
import path from 'path';
import type { PluginContext } from './types';
import type { Page } from './types';
import { PluginPipeline } from './plugin';
import { loadConfig, loadPluginsFromConfig, resolveConfigPath } from './plugin-loader';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/template';
import { DevServerPlugin } from './plugins/dev-server';

export interface EngineOptions {
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  configPath?: string;
}

function emptyTemplateSet(dir: string): PluginContext['templates'] {
  return { dir, templates: new Map(), layouts: new Map(), partials: new Map() };
}

export class SSGEngine {
  readonly context: PluginContext;
  readonly pipeline: PluginPipeline;

  constructor(options: EngineOptions) {
    const config = loadConfig(options.configPath);
    const configPath = resolveConfigPath(options.configPath);
    const configDir = configPath ? path.dirname(configPath) : process.cwd();

    this.context = {
      config,
      contentDir: options.contentDir,
      outputDir: options.outputDir,
      templatesDir: options.templatesDir,
      pages: [],
      templates: emptyTemplateSet(options.templatesDir),
      output: {},
    };

    this.pipeline = new PluginPipeline();
    this.pipeline.add(new MarkdownPlugin());
    this.pipeline.add(new TemplatePlugin());
    this.pipeline.add(new DevServerPlugin());
    for (const plugin of loadPluginsFromConfig(config, configDir)) {
      this.pipeline.add(plugin);
    }
  }

  build(): Page[] {
    const ctx = this.context;
    fs.mkdirSync(ctx.outputDir, { recursive: true });

    this.pipeline.onStart(ctx);
    this.pipeline.beforeBuild(ctx);

    for (const page of ctx.pages) {
      this.pipeline.onFile(page, ctx);
    }

    this.pipeline.afterBuild(ctx);
    this.pipeline.onEnd(ctx);

    return ctx.pages;
  }

  async buildAsync(): Promise<Page[]> {
    const ctx = this.context;
    fs.mkdirSync(ctx.outputDir, { recursive: true });

    await this.pipeline.runAsync('onStart', ctx);
    await this.pipeline.runAsync('beforeBuild', ctx);

    for (const page of ctx.pages) {
      await this.pipeline.runAsync('onFile', page, ctx);
    }

    await this.pipeline.runAsync('afterBuild', ctx);
    await this.pipeline.runAsync('onEnd', ctx);

    return ctx.pages;
  }
}

import { SSGEngine } from './engine';
import type { Page } from './types';

export type { Page } from './types';

export { FRONTMATTER_DELIMITERS, parseMarkdown, readPages, sortPages } from './markdown';
export {
  escapeHtml,
  pageContext,
  renderIndex,
  renderIndexWithTemplates,
  renderPage,
  renderPageWithTemplates,
} from './render';
export {
  DEFAULT_LAYOUT,
  DEFAULT_TEMPLATE,
  DEFAULT_TEMPLATES_DIR,
  detectEngine,
  loadTemplates,
  renderTemplateFile,
} from './templates';
export type { TemplateEngine, TemplateFile, TemplateSet } from './templates';

export { SSGEngine } from './engine';
export type { EngineOptions } from './engine';

export { PluginPipeline, PLUGIN_HOOKS } from './plugin';
export type { Plugin, PluginContext, PluginHook, SSGConfig } from './types';

export { MarkdownPlugin } from './plugins/markdown';
export { TemplatePlugin } from './plugins/template';
export { DevServerPlugin } from './plugins/dev-server';

export {
  DEFAULT_CONFIG_FILE,
  DEFAULT_PLUGINS_DIR,
  ensureTypeScriptLoader,
  loadConfig,
  loadPlugin,
  loadPluginsFromConfig,
  loadTsModule,
  normalizeConfig,
  resolveConfigPath,
  toPlugin,
} from './plugin-loader';

export const DEFAULT_CONTENT_DIR = './content';
export const DEFAULT_OUTPUT_DIR = './dist';

/**
 * Generate the whole site: the engine reads Markdown from `contentDir`, runs
 * the built-in plugin pipeline (markdown, templates, live-reload helpers) plus
 * any plugins registered in `ssg.config.ts`, and writes one HTML file per page
 * into `outputDir` plus an `index.html`. Returns the pages.
 */
export function build(
  contentDir: string = DEFAULT_CONTENT_DIR,
  outputDir: string = DEFAULT_OUTPUT_DIR,
  templatesDir: string = DEFAULT_TEMPLATES_DIR
): Page[] {
  return new SSGEngine({ contentDir, outputDir, templatesDir }).build();
}

